<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import DashboardStatCard from '@/components/DashboardStatCard.vue';
import DashboardFooter from '@/components/DashboardFooter.vue';
import DashboardLayout from '@/layouts/DashboardLayout.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import PasswordInput from '@/components/PasswordInput.vue';
import PaginationControls from '@/components/PaginationControls.vue';
import { api, errorMessage } from '@/api/client';
import type { ApiResponse, Pagination } from '@/types/api';
interface Alumni { id: string; email: string; isActive: boolean; alumniProfile: { fullName: string; graduationYear: number | null; occupation: string | null; location: string | null; profileImage: string | null } | null; }
const users = ref<Alumni[]>([]), selected = ref<Alumni | null>(null), pagination = ref<Pagination | null>(null), search = ref(''), year = ref(''), active = ref(''), page = ref(1), password = ref(''), error = ref(''), notice = ref(''), loading = ref(false), busy = ref(false);
const years = Array.from({ length: new Date().getFullYear() - 1899 }, (_, i) => new Date().getFullYear() - i);
const activeOnPage = computed(() => users.value.filter(user => user.isActive).length);
function exportPage() {
 const rows = [['Name', 'Email', 'Graduation year', 'Profession', 'Location', 'Account status'], ...users.value.map(user => [user.alumniProfile?.fullName || '', user.email, String(user.alumniProfile?.graduationYear || ''), user.alumniProfile?.occupation || '', user.alumniProfile?.location || '', user.isActive ? 'Active' : 'Disabled'])];
 const csv = rows.map(row => row.map(value => '"' + (/^[=+@\-\t\r\n]/.test(value) ? "'" + value : value).replace(/"/g, '""') + '"').join(',')).join('\r\n');
 const url = URL.createObjectURL(new Blob(['\ufeff', csv], { type: 'text/csv;charset=utf-8' }));
 const link = document.createElement('a'); link.href = url; link.download = `gda-alumni-page-${page.value}.csv`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
}
async function load(next = 1) { page.value = next; loading.value = true; error.value = ''; try { const response = await api.get<ApiResponse<Alumni[]>>('/admin/alumni', { params: { page: next, search: search.value, active: active.value || undefined, graduationYear: year.value || undefined } }); users.value = response.data.data; pagination.value = response.data.pagination; } catch (e) { error.value = errorMessage(e); } finally { loading.value = false; } }
async function update() { if (!selected.value) return; busy.value = true; error.value = ''; try { await api.patch(`/admin/alumni/${selected.value.id}/${selected.value.isActive ? 'disable' : 'enable'}`, { currentPassword: password.value }); notice.value = 'Alumni account status updated. Previous sessions are revoked. Membership evidence is unchanged.'; selected.value = null; password.value = ''; await load(page.value); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
onMounted(load);
</script>
<template><DashboardLayout><header class="flex flex-wrap items-center justify-between gap-4 border-b border-slate-200 bg-white px-4 py-6 md:px-8"><div><h1 class="text-h2 text-primary">Alumni Management</h1><p class="mt-1 text-caption text-secondary">Registry of former students and institutional affiliates.</p></div><div class="flex flex-wrap gap-4"><button class="dashboard-action" :disabled="loading || !users.length" @click="exportPage"><span aria-hidden="true" class="material-symbols-outlined">cloud_download</span>Export current page</button><RouterLink to="/admin/membership" class="dashboard-action dashboard-action-primary"><span aria-hidden="true" class="material-symbols-outlined">person_add</span>Membership applications</RouterLink></div></header><section class="mx-auto max-w-7xl space-y-8 p-4 md:p-8"><ApiAlert :message="error"/><ApiAlert :message="notice" kind="success"/><form class="grid items-end gap-4 rounded border border-slate-200 bg-white p-6 shadow-sm md:grid-cols-4" @submit.prevent="load()"><div class="min-w-0 md:col-span-2"><label for="alumni-manage-search" class="field-label">Search alumni name or email</label><div class="relative"><span aria-hidden="true" class="material-symbols-outlined absolute left-3 top-3 text-outline">search</span><input id="alumni-manage-search" v-model.trim="search" maxlength="150" class="field-input pl-10" placeholder="Search by name or email…"></div></div><div><label for="alumni-manage-year" class="field-label">Graduation Year</label><select id="alumni-manage-year" v-model="year" class="field-input"><option value="">All Years</option><option v-for="value in years" :key="value" :value="value">{{ value }}</option></select></div><button class="dashboard-action h-12" :disabled="loading">Search</button><div><label for="alumni-manage-status" class="field-label">Account status</label><select id="alumni-manage-status" v-model="active" class="field-input"><option value="">All</option><option value="true">Active</option><option value="false">Disabled</option></select></div></form><p v-if="loading" role="status">Loading alumni…</p><button v-if="error" class="secondary-button" :disabled="loading" @click="load(page)">Try again</button><section class="overflow-hidden rounded border border-slate-200 bg-white shadow-sm"><div role="region" aria-label="Alumni accounts" tabindex="0" class="overflow-x-auto"><table class="w-full min-w-[900px] text-left"><caption class="sr-only">Alumni accounts and permitted access actions</caption><thead class="border-b border-slate-200 bg-surface-container-low text-label-sm uppercase tracking-wider text-on-surface-variant"><tr><th scope="col" class="px-6 py-4">Alumnus Name</th><th scope="col" class="px-6 py-4">Class</th><th scope="col" class="px-6 py-4">Profession</th><th scope="col" class="px-6 py-4">Current Location</th><th scope="col" class="px-6 py-4">Status</th><th scope="col" class="px-6 py-4 text-right">Actions</th></tr></thead><tbody v-if="!loading" class="divide-y divide-slate-100"><tr v-for="user in users" :key="user.id" class="hover:bg-slate-50"><td class="px-6 py-5"><div class="flex items-center gap-3"><img v-if="user.alumniProfile?.profileImage" :src="user.alumniProfile.profileImage" alt="" referrerpolicy="no-referrer" class="h-10 w-10 shrink-0 rounded-full border border-slate-200 object-cover"><span v-else aria-hidden="true" class="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-primary-container text-xs font-bold text-white">{{ (user.alumniProfile?.fullName || 'Alumni member').split(' ').map(part => part[0]).slice(0, 2).join('') }}</span><div><p class="text-label-sm text-on-surface">{{ user.alumniProfile?.fullName || 'Alumni member' }}</p><p class="mt-1 text-caption text-secondary">{{ user.email }}</p></div></div></td><td class="px-6 py-5">{{ user.alumniProfile?.graduationYear ?? 'Not provided' }}</td><td class="px-6 py-5">{{ user.alumniProfile?.occupation || 'Not provided' }}</td><td class="px-6 py-5">{{ user.alumniProfile?.location || 'Not provided' }}</td><td class="px-6 py-5"><span class="rounded px-2.5 py-1 text-[11px] font-bold uppercase" :class="user.isActive ? 'bg-green-100 text-green-800' : 'bg-red-50 text-error'">{{ user.isActive ? 'Active' : 'Disabled' }}</span></td><td class="px-6 py-5"><div class="flex justify-end gap-2"><RouterLink v-if="user.isActive && user.alumniProfile?.fullName" :to="{ path: '/alumni', query: { search: user.alumniProfile.fullName } }" class="rounded p-2 text-primary hover:bg-slate-100" aria-label="View directory profile"><span aria-hidden="true" class="material-symbols-outlined">visibility</span></RouterLink><button class="rounded p-2 text-secondary hover:bg-slate-100" :aria-label="user.isActive ? 'Disable account' : 'Enable account'" :disabled="busy" @click="selected = user; password = ''"><span aria-hidden="true" class="material-symbols-outlined">{{ user.isActive ? 'person_off' : 'person_add' }}</span></button></div></td></tr></tbody></table></div><p v-if="!users.length && !loading" class="p-6">No matching alumni accounts.</p><div class="border-t border-slate-200 bg-surface-container-low px-6 py-4"><PaginationControls :page="page" :pagination="pagination" :busy="loading || busy" @change="load"/></div></section><div class="grid gap-6 md:grid-cols-3"><DashboardStatCard label="Matching accounts" :value="pagination?.total ?? 0" icon="groups" note="All pages with current filters"/><DashboardStatCard label="Active accounts" :value="activeOnPage" icon="verified_user" note="On the current page"/><DashboardStatCard label="Disabled accounts" :value="users.length - activeOnPage" icon="person_off" note="On the current page"/></div><form v-if="selected" class="space-y-5 border bg-white p-6" @submit.prevent="update"><h2 class="text-h2">Confirm account status change</h2><p class="break-all">{{ selected.email }}</p><p>This changes account access, preserves school records and revokes previous sessions.</p><label for="alumni-status-password" class="field-label">Your current password</label><PasswordInput id="alumni-status-password" v-model="password" required autocomplete="current-password"/><div class="flex flex-wrap gap-3"><button class="primary-button" :disabled="busy">Confirm {{ selected.isActive ? 'disable' : 'enable' }}</button><button type="button" class="secondary-button" @click="selected = null; password = ''">Cancel</button></div></form><DashboardFooter/></section></DashboardLayout></template>
